export function Diseases({accession}:{accession:string}){
 const [search,setSearch]=useSearchParams();const panel=search.get('disease_panel');const ptmdOpen=panel==='ptmd',clinvarOpen=panel==='clinvar';
 const openPanel=(name:'ptmd'|'clinvar')=>setSearch(()=>{const next=new URLSearchParams(window.location.search);next.set('disease_panel',name);next.delete('diseases_source');next.delete('diseases_view');return next;},{replace:true});
 const closePanel=()=>setSearch(previous=>{const next=new URLSearchParams(previous);next.delete('disease_panel');return next;},{replace:true});
 const summary=useSummary(accession,'diseases');const clinvar=useClinvarConditionSummary(accession);const listing=useContextListing(accession,'diseases',['source']);const [selected,setSelected]=useState<string|null>(null);const {query,filters,pager}=listing;const sources=groupsBy(summary.data,'source');const dosage=summary.data?.gene_dosage??query.data?.gene_dosage??[];
 const descriptions:Record<string,string>={ClinGen:'Curated relationships and activity summaries',GenCC:'Submitted gene–disease relationships',HPO:'Gene–disease links with phenotype context',OMIM:'Gene and phenotype catalog relationships'};
 const columns:ColumnDef<RecordData>[]=[
  {id:'name',header:'Disease',cell:({row})=><div className="cx-disease-name"><button className="text-button" onClick={()=>setSelected(String(row.original.disease_id))}>{display(row.original.name)}<ArrowUpRight size={14}/></button>{Boolean(row.original.disease_id)&&<small>{display(row.original.disease_id)}</small>}</div>},
  ...(!filters.source?[{accessorKey:'source',header:'Source',cell:({getValue}:{getValue:()=>unknown})=><span>{display(getValue())}</span>} as ColumnDef<RecordData>]:[]),
  {accessorKey:'classification',header:'Source classification',cell:({row})=><DiseaseClassification source={row.original.source} value={row.original.classification}/>},
  {accessorKey:'inheritance',header:'Inheritance',cell:({getValue})=><span className="cx-inheritance"><Val value={getValue()}/></span>},
  ...(filters.source==='GenCC'?[{accessorKey:'submitter',header:'Submitting organization',cell:({getValue}:{getValue:()=>unknown})=><span className="cx-submitter"><Val value={getValue()}/></span>} as ColumnDef<RecordData>]:[{accessorKey:'relationship_status',header:'Relationship',cell:({getValue}:{getValue:()=>unknown})=><Val value={optionalLabel(getValue())}/>} as ColumnDef<RecordData>]),
  {id:'source-link',header:'Report',cell:({row})=>reportUrl(row.original.report_url)?<LinkOut href={row.original.report_url}>Source report</LinkOut>:null},
 ];
 return <ContextFrame id="diseases" title="Diseases & phenotypes" subtitle="Gene–disease and phenotype evidence" tone="rose" icon={<HeartPulse size={22}/>}><Status loading={summary.isPending} error={summary.error} empty={!summary.data?.groups.length}><div className="cx-disease-sources">{sources.map(group=><button key={group.key} className={`cx-disease-card${group.count===0?' is-empty':''}${filters.source===group.source?' is-selected':''}`} onClick={()=>listing.open(group.filter)} disabled={group.count===0||group.count===null} style={{'--cx-source':sourceColors[group.source??group.label]??'var(--cx-accent)'} as CSSProperties}><div className="cx-disease-source-title"><span className="cx-source-dot"/><strong>{group.source??group.label}</strong><ArrowUpRight size={15}/></div><p><small>Evidence</small>{descriptions[group.source??group.label]??group.label}</p><div className="cx-disease-count"><strong>{group.count===null?'—':number(group.count,0)}</strong><span>{group.unit?group.unit.replaceAll('_',' '):'source records'}</span></div>{group.diseases!==undefined&&<div className="cx-disease-identifiers">{number(group.diseases,0)} disease identifiers</div>}</button>)}<button className={`cx-disease-card${clinvarOpen?' is-selected':''}${clinvar.data?.totals.condition_sets===0?' is-empty':''}`} onClick={()=>openPanel('clinvar')} disabled={clinvar.data?.totals.condition_sets===0} style={{'--cx-source':sourceColors.ClinVar} as CSSProperties}><div className="cx-disease-source-title"><span className="cx-source-dot"/><strong>ClinVar</strong><ArrowUpRight size={15}/></div><p><small>Evidence</small>Current variant_summary condition sets · SNVs only</p><div className="cx-disease-count"><strong>{clinvar.isPending?'…':clinvar.data?number(clinvar.data.totals.condition_sets,0):'—'}</strong><span>exact condition sets</span></div><div className="cx-disease-identifiers">{clinvar.data?`${number(clinvar.data.totals.variants,0)} current SNVs`:'Current-summary scope'} · condition-level RCV/SCV unresolved</div></button>{summary.data?.ptmd&&<button className={`cx-disease-card cx-ptmd-card${ptmdOpen?' is-selected':''}${summary.data.ptmd.records===0?' is-empty':''}`} onClick={()=>openPanel('ptmd')} disabled={summary.data.ptmd.records===0} style={{'--cx-source':sourceColors.PTMD2} as CSSProperties}><div className="cx-disease-source-title"><span className="cx-source-dot"/><strong>PTMD2</strong><ArrowUpRight size={15}/></div><p><small>Evidence</small>PTM and disease context from original source records</p><div className="cx-disease-count"><strong>{number(summary.data.ptmd.records,0)}</strong><span>source PTM disease records</span></div><div className="cx-disease-identifiers">{number(summary.data.ptmd.disease_labels,0)} original disease labels</div></button>}</div></Status>
  {clinvarOpen?<ClinvarConditionBrowser accession={accession} onClose={closePanel}/>:ptmdOpen?<PtmdDiseaseRecords accession={accession} onClose={closePanel}/>:listing.active?<RecordArea title={`${filters.source||'All source'} evidence`} onClose={listing.close}>{filters.source==='GenCC'&&<div className="cx-classification-guide"><span>Each row is a separate submitted gene–disease assertion.</span><HelpButton title="GenCC source classifications" label="Classification guide"><p>Definitive, Strong, Moderate and Limited describe source support for a gene–disease relationship. Supportive is a broader category for resources that do not use the finer GenCC grades; it is not an intermediate score.</p><p>Disputed and Refuted express contrary evidence. Animal Model Only and No Known Disease Relationship describe different evidence scopes. These are gene–disease classifications, not classifications of individual variants.</p><LinkOut href="https://clinicalgenome.org/docs/gencc/">Official GenCC terminology</LinkOut><LinkOut href="https://www.clinicalgenome.org/docs/gene-disease-validity-classification-information/">ClinGen validity definitions</LinkOut></HelpButton></div>}<Status loading={query.isPending} error={query.error} empty={!query.data?.items.length}><div className={`cx-disease-table${!filters.source?' is-mixed':''}`}><DataTable items={query.data?.items??[]} columns={columns}/></div></Status>{pager.page===0&&!pager.next&&!query.isPending?<p className="cx-record-count">{number(query.data?.items.length??0,0)} source assertions</p>:<Pager {...pager}/>}</RecordArea>:<SelectHint>Select a source to view its disease relationships. Assertions from different resources remain separate.</SelectHint>}
  {dosage.length>0&&<Disclosure title="Gene dosage sensitivity · ClinGen">{dosage.map((row,index)=><div className="annotation" key={index}><Fields items={[{label:'Gene',value:row.gene_symbol},{label:'Haploinsufficiency',value:row.haploinsufficiency},{label:'Triplosensitivity',value:row.triplosensitivity}]}/><LinkOut href={row.report_url}>ClinGen dosage report</LinkOut></div>)}</Disclosure>}
  <SummaryNotes summary={summary.data} fallback="Gene–disease assertions and disease-associated phenotypes are contextual evidence. They do not classify every variant in the gene."/>{selected&&<DiseaseDetail id={selected} accession={accession} onClose={()=>setSelected(null)}/>}</ContextFrame>;
}
